   "cap_id": "P0150",
   "a": {
    "unit_id": "BLLD_45-2019.D27.K1",
    "tieu_de_dieu": "Kết thúc thời gian thử việc",
    "khoan_cha": "",
    "chu_don_vi": "Khi kết thúc thời gian thử việc, người sử dụng lao động phải thông báo kết quả thử việc cho người lao động.\nTrường hợp thử việc đạt yêu cầu thì người sử dụng lao động tiếp tục thực hiện hợp đồng lao động đã giao kết đối với trường hợp thỏa thuận thử việc trong hợp đồng lao động hoặc phải giao kết hợp đồng lao động đối với trường hợp giao kết hợp đồng thử việc.\nTrường hợp thử việc không đạt yêu cầu thì chấm dứt hợp đồng lao động đã giao kết hoặc hợp đồng thử việc."
   },
   "b": {
    "unit_id": "BLLD_45-2019.D175.K1.a",
    "tieu_de_dieu": "Các hành vi bị nghiêm cấm đối với người sử dụng lao động liên quan đến thành lập, gia nhập và hoạt động của tổ chức đại diện người lao động tại cơ sở",
    "khoan_cha": "Phân biệt đối xử đối với người lao động, thành viên ban lãnh đạo của tổ chức đại diện người lao động tại cơ sở vì lý do thành lập, gia nhập hoặc hoạt động tổ chức đại diện người lao động, bao gồm:",
    "chu_don_vi": "Yêu cầu tham gia, không tham gia hoặc ra khỏi tổ chức đại diện người lao động tại cơ sở để được tuyển dụng, giao kết hoặc gia hạn hợp đồng lao động;"
   },
   "vi_tu_chung": [
    "conclude_employment_contract"
   ]
